css:
.powergrid-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #0d1b2a;
    background: linear-gradient(170deg, #0a1626 0%, #0d2438 45%, #11324b 100%);
    border-radius: 18px;
}

.powergrid-container * {
    box-sizing: border-box;
}

.powergrid-header {
    text-align: center;
    padding: 30px 22px 26px;
    background:
        radial-gradient(circle at 50% 120%, rgba(255, 183, 77, 0.34) 0%, rgba(255, 183, 77, 0) 60%),
        linear-gradient(135deg, #07111f 0%, #0f2c46 60%, #15507a 100%);
    color: #eaf4ff;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 16px 38px rgba(3, 10, 20, 0.55);
    border: 1px solid rgba(86, 168, 230, 0.22);
}

.powergrid-header h1 {
    margin: 12px 0 12px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
    text-shadow: 0 2px 18px rgba(255, 183, 77, 0.35);
}

.powergrid-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd089;
    background: rgba(255, 183, 77, 0.12);
    border: 1px solid rgba(255, 183, 77, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.powergrid-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #bcd8f0;
}

.powergrid-targets {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.powergrid-target {
    flex: 1;
    background: rgba(11, 32, 51, 0.72);
    border-radius: 14px;
    padding: 14px 18px;
    border: 1px solid rgba(86, 168, 230, 0.20);
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.powergrid-target-capacity { border-left: 5px solid #43d39e; }
.powergrid-target-access { border-left: 5px solid #ffb74d; }
.powergrid-target-fiscal { border-left: 5px solid #ff6b6b; }

.powergrid-target-name {
    font-weight: 800;
    font-size: 1rem;
    color: #eaf4ff;
}

.powergrid-target-capacity .powergrid-target-name { color: #43d39e; }
.powergrid-target-access .powergrid-target-name { color: #ffc266; }
.powergrid-target-fiscal .powergrid-target-name { color: #ff8585; }

.powergrid-target-meta {
    font-size: 0.8rem;
    color: #9fc0dc;
    line-height: 1.42;
}

.powergrid-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #bcd8f0;
    margin-bottom: 16px;
    padding: 4px;
}

.powergrid-period-counter #currentDay,
.powergrid-period-counter #maxPeriods {
    font-weight: 800;
    color: #5fd0ff;
}

.powergrid-round-name {
    background: rgba(95, 208, 255, 0.16);
    color: #8fe0ff;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.powergrid-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffd089;
    background: rgba(255, 183, 77, 0.14);
    border: 1px solid rgba(255, 183, 77, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.powergrid-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.powergrid-status-card {
    background: linear-gradient(180deg, #ffffff 0%, #f3f8fc 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 8px 20px rgba(3, 10, 20, 0.40);
    border-top: 4px solid #15507a;
}

.powergrid-card-capacity { border-top-color: #1f9e76; }
.powergrid-card-access { border-top-color: #e08a1e; }
.powergrid-card-price { border-top-color: #2563a8; }
.powergrid-card-subsidy { border-top-color: #d64545; }

.powergrid-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5d7184;
}

.powergrid-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0d2438;
    font-variant-numeric: tabular-nums;
}

.powergrid-card-capacity .powergrid-value { color: #18815f; }
.powergrid-card-access .powergrid-value { color: #c8780f; }
.powergrid-card-price .powergrid-value { color: #2563a8; }
.powergrid-card-subsidy .powergrid-value { color: #18815f; }

.powergrid-sublabel {
    font-size: 0.75rem;
    color: #6b7d8d;
    line-height: 1.35;
}

.powergrid-card-capacity.powergrid-cap-good { border-top-color: #1f9e76; }
.powergrid-card-capacity.powergrid-cap-good .powergrid-value { color: #18815f; }
.powergrid-card-capacity.powergrid-cap-bad { border-top-color: #d64545; }
.powergrid-card-capacity.powergrid-cap-bad .powergrid-value { color: #d64545; }

.powergrid-card-subsidy.powergrid-sub-breach { border-top-color: #d64545; }
.powergrid-card-subsidy.powergrid-sub-breach .powergrid-value { color: #d64545; }

.powergrid-cred-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: rgba(11, 32, 51, 0.72);
    border: 1px solid rgba(86, 168, 230, 0.22);
    color: #bcd8f0;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.powergrid-cred-bar #credDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ff8585;
    font-weight: 800;
}

.powergrid-cred-bar.powergrid-cred-high #credDisplay { color: #43d39e; }
.powergrid-cred-bar.powergrid-cred-mid #credDisplay { color: #ffc266; }

.powergrid-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(180deg, #ffffff 0%, #f3f8fc 100%);
    border-left: 5px solid #ffb74d;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(3, 10, 20, 0.35);
}

.powergrid-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.powergrid-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #0d2438;
    margin-bottom: 6px;
}

.powergrid-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3d4e;
}

.powergrid-briefing-text strong { color: #15507a; }
.powergrid-briefing-text em { color: #c8780f; font-style: italic; }

.powergrid-controls {
    background: linear-gradient(180deg, #ffffff 0%, #f4f8fc 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(3, 10, 20, 0.35);
}

.powergrid-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0d2438;
    border-bottom: 2px solid #e1ebf2;
    padding-bottom: 8px;
}

.powergrid-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #21384a;
    margin: 14px 0 6px;
}

.powergrid-container select,
.powergrid-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcccd9;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #0d2438;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.powergrid-container select:focus,
.powergrid-container input[type="number"]:focus {
    outline: none;
    border-color: #2563a8;
    box-shadow: 0 0 0 3px rgba(37, 99, 168, 0.16);
}

.powergrid-container select option {
    background-color: #ffffff;
    color: #0d2438;
}

.powergrid-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2563a8;
}

.powergrid-range-readout {
    font-size: 0.86rem;
    font-weight: 700;
    color: #46596b;
    margin-top: 4px;
}

.powergrid-range-readout span:nth-child(2) {
    color: #2563a8;
    font-weight: 800;
}

.powergrid-hint {
    font-size: 0.8rem;
    color: #6b7d8d;
    margin-top: 8px;
    line-height: 1.42;
    font-style: italic;
    border-left: 3px solid #ffd089;
    padding-left: 10px;
}

.powergrid-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.powergrid-container .btn-primary {
    background: linear-gradient(135deg, #15507a 0%, #2563a8 55%, #1f9e76 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(21, 80, 122, 0.45);
}

.powergrid-container .btn-primary:hover {
    filter: brightness(1.08);
}

.powergrid-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #bcccd9;
    color: #5a6b7a;
    background: transparent;
}

.powergrid-coach {
    background: linear-gradient(160deg, #07111f 0%, #0f2c46 100%);
    color: #d4e8f8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 10px 24px rgba(3, 10, 20, 0.45);
    border: 1px solid rgba(86, 168, 230, 0.22);
}

.powergrid-coach-header {
    font-size: 0.77rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd089;
    margin-bottom: 8px;
}

.powergrid-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.powergrid-coach-body strong { color: #6fe3c0; }
.powergrid-coach-body em { color: #ffd089; font-style: italic; }

.powergrid-history,
.powergrid-chart {
    background: linear-gradient(180deg, #ffffff 0%, #f4f8fc 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(3, 10, 20, 0.35);
}

.powergrid-history h3,
.powergrid-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0d2438;
}

.powergrid-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c3d4e;
}

.powergrid-container table#usfHistoryTable th {
    background: #e9f1f8;
    color: #15507a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d3e1ec;
}

.powergrid-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef3f7;
    color: #2c3d4e;
}

.powergrid-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6fafd;
}

.powergrid-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .powergrid-container {
        padding: 14px;
    }
    .powergrid-header h1 {
        font-size: 1.8rem;
    }
    .powergrid-targets {
        flex-direction: column;
    }
    .powergrid-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .powergrid-value {
        font-size: 2rem;
    }
    .powergrid-clock {
        margin-left: 0;
    }
    .powergrid-period-counter {
        font-size: 0.88rem;
    }
    .powergrid-cred-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .powergrid-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================
   Power the Grid — completion debrief (v1.1.0, append-only)
   Namespaced .pg-cm-* ; rendered into #usf-completion-content.
   ============================================================ */
.pg-cm { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; color: #1f2a37; }
.pg-cm-verdict { display: flex; align-items: center; gap: 18px; padding: 16px 18px; border-radius: 12px;
    background: linear-gradient(135deg, #eef6f2 0%, #f4f8fb 100%); border: 1px solid #dbe7e1; margin-bottom: 18px; }
.pg-cm-top .pg-cm-verdict { background: linear-gradient(135deg, #e3f5ec 0%, #eaf3fb 100%); border-color: #1f9e76; }
.pg-cm-score { flex: 0 0 auto; min-width: 92px; text-align: center; line-height: 1; }
.pg-cm-score-num { font-size: 2.9rem; font-weight: 800; color: #1f9e76; }
.pg-cm-score-den { font-size: 1.1rem; font-weight: 600; color: #76889a; }
.pg-cm-top .pg-cm-score-num { color: #14855f; }
.pg-cm-verdict-txt { flex: 1 1 auto; }
.pg-cm-badge { font-size: 1.35rem; font-weight: 700; color: #1f2a37; margin-bottom: 3px; }
.pg-cm-sub { font-size: 0.9rem; color: #76889a; }
.pg-cm-h { font-size: 0.82rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em;
    color: #46596b; margin: 16px 0 8px; }
.pg-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.pg-cm-chip { display: inline-flex; align-items: center; gap: 5px; padding: 5px 11px; border-radius: 16px;
    font-size: 0.86rem; font-weight: 600; border: 1px solid transparent; }
.pg-cm-chip-ok { background: rgba(31,158,118,0.12); color: #14855f; border-color: rgba(31,158,118,0.35); }
.pg-cm-chip-no { background: rgba(214,69,69,0.10); color: #b23b3b; border-color: rgba(214,69,69,0.30); }
.pg-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 10px; }
.pg-cm-kpi { background: #f8fafc; border: 1px solid #e6edf3; border-radius: 10px; padding: 11px 12px; text-align: center; }
.pg-cm-kpi-val { font-size: 1.25rem; font-weight: 800; color: #1f2a37; }
.pg-cm-kpi-lbl { font-size: 0.76rem; font-weight: 600; color: #46596b; margin-top: 3px; line-height: 1.2; }
.pg-cm-kpi-sub { font-size: 0.7rem; color: #93a3b3; margin-top: 2px; }
.pg-cm-insights { margin: 0; padding-left: 18px; }
.pg-cm-insights li { font-size: 0.9rem; line-height: 1.5; color: #33414f; margin-bottom: 7px; }
/* Dark theme (framework toggles .usf-dark on <html>) */
.usf-dark .pg-cm { color: #e6edf3; }
.usf-dark .pg-cm-verdict { background: linear-gradient(135deg, #1b2b25 0%, #1a2632 100%); border-color: #2c4038; }
.usf-dark .pg-cm-badge { color: #e6edf3; }
.usf-dark .pg-cm-kpi { background: #1a2230; border-color: #2a3646; }
.usf-dark .pg-cm-kpi-val { color: #e6edf3; }
.usf-dark .pg-cm-insights li { color: #c4d0dc; }


/* Focus visibility + reduced motion (EQIL a11y pass 2026-07-28) */
.powergrid-panel select:focus-visible,
.powergrid-panel input:focus-visible,
#nextPeriodBtn:focus-visible,
#undoBtn:focus-visible {
    outline: 2px solid currentColor;
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .powergrid-panel, #nextPeriodBtn, #undoBtn { transition: none; animation: none; }
}

