(function() {
    'use strict';

    class PowerTheGridAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Power the Grid`;
            this.version = `1.2.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ----- Numbers reference card (Republic of Zambeka / ZMK) -----
            this.CAP_TARGET = 600;        // MW Cabinet target
            this.ACCESS_START = 43;       // % national access at day 0
            this.ACCESS_TARGET = 60;      // % five-year target
            this.SUBSIDY_CEILING = 4.1;   // ZMK billion/yr ceiling
            this.TARIFF_START = 0.92;     // ZMK/kWh average retail tariff
            this.COST_REFLECTIVE_GAP = 29;// % gap (tariffs recover 71% of cost)
            this.RISK_PREMIUM = 0.40;     // ZMK/kWh added when offtaker risk is uncovered
            this.GRID_COST = 9500;        // ZMK/connection grid extension
            this.OFFGRID_COST = 3200;     // ZMK/connection off-grid / mini-grid

            // Concept "best" answers used only for the per-round move summary.
            this.TRUE_CONSTRAINT = `creditworthiness`;
            this.TRUE_SYSTEMS = `system`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    capacityMW: 0,             // delivered MW toward 600
                    accessPct: this.ACCESS_START,
                    clearingPrice: 0,          // ZMK/kWh projected winning bid (0 = not yet auctioned)
                    subsidyDrawn: this.SUBSIDY_CEILING, // start AT the ceiling (diesel-dependent baseline)
                    credibility: 38,           // investor & programme credibility 0–100 (fragile)

                    // ----- Sticky run-defining penalty flags (concept anti-patterns) -----
                    auctionFailed: false,      // reserve price too low → under-subscription
                    riskUncovered: false,      // skipped credit enhancement → invisible premium
                    tariffRollback: false,     // full shock in one step → politically reversed
                    gridOnly: false,           // poured access budget into grid extension
                    silosThinking: false,      // treated the three levers as independent
                    shellAwarded: false,       // awarded a politically connected shell bidder
                    subsidyBreached: false,    // ever broke the ZMK 4.1bn ceiling

                    diagnosedConstraint: false,// correctly named tariff/creditworthiness
                    framingSound: true,        // R4: led with the integrated balance + staked delivered MW
                    tariffUnreformed: true,     // until a cost-reflective path (glide / shielded shock) is chosen
                    shockMishandled: false,     // R4: answered the live shock with the reform-breaking trap
                    householdsReached: 0,      // thousands of households connected

                    capacityHistory: [0],
                    accessHistory: [this.ACCESS_START],
                    subsidyHistory: [this.SUBSIDY_CEILING],
                    credibilityHistory: [38],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    constraint: `generation`,
                    risk: `capacity`,
                    systems: `independent`,
                    rigour: 35,
                    volume: 600,
                    reserve: `low`,
                    credit: `none`,
                    qual: `loose`,
                    content: 30,
                    tariff: `shock`,
                    lifeline: `no`,
                    accessSplit: 15,
                    incentive: `costplus`,
                    shock: `shell`,
                    defense: `spin`,
                    metric: `mw`,
                    conviction: 50
                };
            }
            this._syncControlsFromDecisions(state);
            this._updateBriefing(state);
        }
        _syncControlsFromDecisions(state) {
            // On resume the framework restores decisions but the DOM still showed the
            // authored defaults, so the player saw values that were not their own.
            const d = state.decisions || {};
            const map = {
                constraintInput: d.constraint,
                riskInput: d.risk,
                systemsInput: d.systems,
                rigourInput: d.rigour,
                volumeInput: d.volume,
                reserveInput: d.reserve,
                creditInput: d.credit,
                qualInput: d.qual,
                contentInput: d.content,
                tariffInput: d.tariff,
                lifelineInput: d.lifeline,
                accessSplitInput: d.accessSplit,
                incentiveInput: d.incentive,
                shockInput: d.shock,
                defenseInput: d.defense,
                metricInput: d.metric,
                convictionInput: d.conviction
            };
            Object.keys(map).forEach((id) => {
                if (map[id] === undefined || map[id] === null) return;
                const el = document.getElementById(id);
                if (el) el.value = map[id];
            });
        }


        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const c = document.getElementById(`constraintInput`);
                const r = document.getElementById(`riskInput`);
                const sy = document.getElementById(`systemsInput`);
                const rg = document.getElementById(`rigourInput`);
                if (c) decisions.constraint = c.value;
                if (r) decisions.risk = r.value;
                if (sy) decisions.systems = sy.value;
                if (rg) decisions.rigour = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const v = document.getElementById(`volumeInput`);
                const rs = document.getElementById(`reserveInput`);
                const cr = document.getElementById(`creditInput`);
                const q = document.getElementById(`qualInput`);
                const ct = document.getElementById(`contentInput`);
                if (v) decisions.volume = parseInt(v.value, 10);
                if (rs) decisions.reserve = rs.value;
                if (cr) decisions.credit = cr.value;
                if (q) decisions.qual = q.value;
                if (ct) decisions.content = parseInt(ct.value, 10);
                if (!Number.isFinite(decisions.volume) || decisions.volume <= 0) {
                    warn(`warn_volume_value`); return false;
                }
                if (!Number.isFinite(decisions.content) || decisions.content < 0 || decisions.content > 60) {
                    warn(`warn_content_range`); return false;
                }
            } else if (round === 3) {
                const t = document.getElementById(`tariffInput`);
                const li = document.getElementById(`lifelineInput`);
                const as = document.getElementById(`accessSplitInput`);
                const inc = document.getElementById(`incentiveInput`);
                if (t) decisions.tariff = t.value;
                if (li) decisions.lifeline = li.value;
                if (as) decisions.accessSplit = parseInt(as.value, 10);
                if (inc) decisions.incentive = inc.value;
                if (!Number.isFinite(decisions.accessSplit) || decisions.accessSplit < 0 || decisions.accessSplit > 100) {
                    warn(`warn_split_range`); return false;
                }
            } else if (round === 4) {
                const sh = document.getElementById(`shockInput`);
                const df = document.getElementById(`defenseInput`);
                const mt = document.getElementById(`metricInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sh) decisions.shock = sh.value;
                if (df) decisions.defense = df.value;
                if (mt) decisions.metric = mt.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        // ---- Composite score — single source of truth. ----
        // Carries the VERBATIM v1.0.0 getPerformanceSummary formula (weights +
        // sticky caps) so the score persisted every period is identical, by
        // construction, to the completion composite. Reads only domainState, so
        // it is safe to call after each round.
        _composite(ds) {
            const capacity    = Math.round(ds.capacityMW);
            const access      = Math.round(ds.accessPct * 10) / 10;
            const subsidy     = Math.round(ds.subsidyDrawn * 100) / 100;
            const credibility = Math.round(ds.credibility);
            const withinCeiling = !ds.subsidyBreached && subsidy <= this.SUBSIDY_CEILING + 0.001;

            const capScore    = Math.min(100, (capacity / this.CAP_TARGET) * 100);
            const accessScore = Math.min(100, ((access - this.ACCESS_START) / (this.ACCESS_TARGET - this.ACCESS_START)) * 100);
            const fiscalScore = withinCeiling ? 100 : Math.max(0, 100 - (subsidy - this.SUBSIDY_CEILING) * 40);
            const priceScore  = ds.clearingPrice > 0
                ? Math.max(0, Math.min(100, 100 - Math.max(0, ds.clearingPrice - 0.78) * 110))
                : 0;
            let composite = Math.round(capScore * 0.26 + accessScore * 0.20 + fiscalScore * 0.20 + credibility * 0.20 + priceScore * 0.14);

            if (ds.auctionFailed)   composite = Math.min(composite, 45);
            if (ds.shellAwarded)    composite = Math.min(composite, 48);
            if (ds.subsidyBreached) composite = Math.min(composite, 52);
            if (ds.tariffRollback)  composite = Math.min(composite, 55);
            if (ds.riskUncovered)   composite = Math.min(composite, 58);
            if (ds.gridOnly)        composite = Math.min(composite, 62);
            return composite;
        }

        // Map the (stable, English) performance tier id to its localized label.
        _gradeLabel(performance) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            // v1.2.0: keyed on the stable ids. The old English display strings are kept
            // as aliases so sessions saved under v1.1.0 still resolve to a verdict.
            const map = {
                powered:      `grade_powered`,
                partial:      `grade_partial`,
                auctionfailed:`grade_auctionfailed`,
                shell:        `grade_shell`,
                breach:       `grade_breach`,
                rollback:     `grade_rollback`,
                mandatelost:  `grade_mandatelost`,
                'Grid Powered':     `grade_powered`,
                'Partial Reform':   `grade_partial`,
                'Auction Failed':   `grade_auctionfailed`,
                'Lights Still Off': `grade_shell`,
                'Ceiling Breached': `grade_breach`,
                'Tariff Reversed':  `grade_rollback`,
                'Mandate Lost':     `grade_mandatelost`
            };
            return t(map[performance] || `grade_mandatelost`);
        }

                calculateResults(state) {
            // Thin wrapper: the round model lives in _computeRound so this method stays
            // short and its return statement is visible to static validators, current and
            // legacy alike. Keep this comment free of apostrophes, quotes and backticks:
            // the importer treats any of them as a string delimiter and desyncs its brace
            // counter, which produced the false empty-method and missing-return errors.
            const r = this._computeRound(state);
            const period = state.currentPeriod;
            return {
                period: period,
                capacityMW: r.capacityMW,
                capDelta: r.capDelta,
                accessPct: r.accessPct,
                clearingPrice: r.clearingPrice,
                subsidyDrawn: r.subsidyDrawn,
                subsidyBreached: r.subsidyBreached,
                credibility: r.credibility,
                auctionFailed: r.auctionFailed,
                summary: r.summary,
                coach: r.coach,
                score: r.score,
                overallScore: r.overallScore
            };
        }

        _computeRound(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let capDelta = 0, accessDelta = 0, subsidyDelta = 0, credDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ----- Diagnose the binding constraint (Common Error 5 / decision tree #5). -----
                switch (d.constraint) {
                    case `creditworthiness`:
                        ds.diagnosedConstraint = true;
                        credDelta += 6; coachKey = `coach_r1_credit`; break;
                    case `generation`:
                        credDelta -= 3; coachKey = `coach_r1_generation`; break;
                    case `access`:
                        credDelta -= 1; coachKey = `coach_r1_access`; break;
                }

                // Which target is most at risk — the fiscal ceiling is the hard constraint.
                if (d.risk === `subsidy`) { credDelta += 3; }
                else if (d.risk === `capacity`) { credDelta -= 1; }

                // Systems thinking vs silos (decision tree #5 — sticky penalty).
                switch (d.systems) {
                    case `system`:
                        credDelta += 5; break;
                    case `independent`:
                        ds.silosThinking = true; credDelta -= 4;
                        if (coachKey === `coach_default`) coachKey = `coach_r1_silos`; break;
                    case `sequential`:
                        credDelta -= 2; break;
                }

                // Diagnostic rigour buffers later mistakes a little.
                if (d.rigour >= 60) { credDelta += 3; }
                else if (d.rigour <= 20) { credDelta -= 2; }

                summaryKey = (d.constraint === `creditworthiness` && d.systems === `system`)
                    ? `sum_r1_good` : `sum_r1_weak`;
                if (d.constraint === `creditworthiness` && d.systems === `system` && d.risk === `subsidy`) {
                    coachKey = `coach_r1_sharp`;
                }
            } else if (round === 2) {
                // ----- Design the auction (the core round). -----
                // Base build cost for a credible renewable IPP in Zambeka (ZMK/kWh).
                const buildCost = 0.62;
                const contentLoad = (d.content / 100) * 0.45; // local-content raises bid price

                // Credit enhancement collapses (or leaves) the offtaker risk premium.
                let premium, creditCost; // creditCost in ZMK bn/yr
                switch (d.credit) {
                    case `prg`:     premium = 0.04; creditCost = 0.18; break;
                    case `escrow`:  premium = 0.22; creditCost = 0.07; break;
                    default:        premium = this.RISK_PREMIUM; creditCost = 0.0; ds.riskUncovered = true; break;
                }

                // Reserve price as a discovery instrument (decision tree #1).
                let reserveCeiling, subscription;
                switch (d.reserve) {
                    case `realistic`: reserveCeiling = 0.85; break;
                    case `high`:      reserveCeiling = 1.20; break;
                    default:          reserveCeiling = 0.55; break; // low
                }

                // A developer's hard cost FLOOR — what it must recover to build at all
                // (build cost + the local-content load). Credit risk is priced ON TOP of
                // this as a premium; it does not stop a project being buildable.
                const costFloor = buildCost + contentLoad;
                // The honest price the market would reveal, premium included.
                const trueClearing = costFloor + premium;

                if (reserveCeiling < costFloor) {
                    // Reserve set below buildable cost (a political statement, not discovery):
                    // the auction under-subscribes — Eberhard's most common African failure.
                    ds.auctionFailed = true;
                    subscription = 0.15; // ~90 MW against a 600 MW tender
                    ds.clearingPrice = reserveCeiling; // only the few token bids at the cap
                    credDelta -= 22;
                    coachKey = `coach_r2_undersubscribed`;
                } else {
                    ds.auctionFailed = false;
                    // It fills. A disciplined reserve just above the buildable floor lets
                    // competition discover a low price near true cost; a generous ceiling
                    // removes that tension, so the price drifts UP toward the cap (overpay).
                    const headroom = reserveCeiling - trueClearing;
                    if (d.reserve === `high`) {
                        // Weak competitive tension → clears well above true cost; ratepayers overpay.
                        ds.clearingPrice = Math.round((trueClearing + headroom * 0.55) * 100) / 100;
                        subscription = 0.90;        // fills, but no discipline reward
                        credDelta -= 6; coachKey = `coach_r2_high`;
                    } else { // realistic
                        // Strong tension → clears just above true cost.
                        ds.clearingPrice = Math.round((trueClearing + headroom * 0.12) * 100) / 100;
                        subscription = 0.90;
                        credDelta += 8; coachKey = `coach_r2_realistic`;
                    }
                }

                // Volume tendered this round → MW procured = volume × subscription.
                const mwProcured = Math.round(d.volume * subscription);
                ds.capacityMW = Math.min(this.CAP_TARGET, ds.capacityMW + mwProcured);

                if (d.volume >= 600 && !ds.auctionFailed) {
                    // Tendering everything at once forgoes a learned second-round price drop.
                    credDelta -= 3;
                    if (coachKey === `coach_r2_realistic`) coachKey = `coach_r2_allvolume`;
                } else if (d.volume <= 150) {
                    credDelta -= 2; coachKey = `coach_r2_token`;
                }

                // Qualification protects delivery (decision tree #6).
                if (d.qual === `strict`) { credDelta += 6; }
                else { credDelta -= 3; }

                // Credit-enhancement fiscal cost draws on the subsidy.
                subsidyDelta += creditCost;

                // Overpay above a disciplined clearing benchmark (~ZMK 0.75/kWh) is carried
                // by ratepayers and the Treasury — a generous ceiling is not free.
                if (!ds.auctionFailed && ds.clearingPrice > 0.78) {
                    subsidyDelta += (ds.clearingPrice - 0.75) * 1.6;
                }

                // The premium is paid either way — uncovered, ratepayers and Treasury carry it.
                if (ds.riskUncovered) {
                    credDelta -= 8;
                    // A high clearing price feeds straight into the subsidy when tariffs lag.
                    subsidyDelta += 0.6;
                    if (!ds.auctionFailed) coachKey = `coach_r2_nocredit`;
                }

                summaryKey = ds.auctionFailed ? `sum_r2_failed`
                    : (d.reserve === `realistic` && d.credit !== `none` && d.qual === `strict`)
                        ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // ----- Tariff path and access plan. -----
                // Tariff trajectory closes the cost-reflectivity gap and refills the subsidy gap.
                // A lifeline block protects the poor AND gives a sharp move the political room
                // to survive — without it, the 30% shock is reversed under pressure.
                const hasLifeline = d.lifeline === `yes`;
                if (hasLifeline) { subsidyDelta += 0.25; credDelta += 4; }
                else { credDelta -= 3; }

                switch (d.tariff) {
                    case `glide`:
                        // Phased path reaches cost-reflectivity by Year 3 and survives the politics.
                        ds.tariffUnreformed = false;
                        subsidyDelta -= 1.1; credDelta += 10; coachKey = `coach_r3_glide`; break;
                    case `shock`:
                        if (hasLifeline) {
                            // A shielded shock reaches FULL cost-reflectivity at once and holds:
                            // the biggest fiscal repair, at some political cost.
                            ds.tariffUnreformed = false;
                            subsidyDelta -= 1.5; credDelta -= 2; coachKey = `coach_r3_shocklifeline`;
                        } else {
                            // Full 30% in one step four months post-by-election → rollback (sticky):
                            // the reversal loses the revenue AND adds arrears. The gap is NOT closed.
                            ds.tariffRollback = true;
                            subsidyDelta += 0.3; credDelta -= 14; coachKey = `coach_r3_shock`;
                        }
                        break;
                    case `freeze`:
                        // Gap and subsidy stay; nothing improves — ZPC stays insolvent.
                        // A frozen tariff is deferred insolvency, never a top-verdict path.
                        subsidyDelta += 0.2; credDelta -= 5; coachKey = `coach_r3_freeze`; break;
                }

                // ----- Access: grid vs off-grid least-cost electrification (decision tree #4). -----
                const accessBudget = 9.5; // ZMK billion notionally available for connections
                const offShare = d.accessSplit / 100;
                const gridShare = 1 - offShare;
                // Households reached (thousands): budget / cost, blended.
                const gridHh = (accessBudget * gridShare * 1e9) / this.GRID_COST;
                const offHh = (accessBudget * offShare * 1e9) / this.OFFGRID_COST;
                const totalHh = Math.round((gridHh + offHh) / 1000); // thousands
                ds.householdsReached = totalHh;

                // 1.9M households = +17 access points. Convert households → access points.
                const accessPointsGained = Math.min(this.ACCESS_TARGET - ds.accessPct,
                    (totalHh * 1000 / 1900000) * (this.ACCESS_TARGET - this.ACCESS_START));
                accessDelta += accessPointsGained;

                if (d.accessSplit <= 5) {
                    // Grid-only optimises the word "grid" over the access number (sticky).
                    ds.gridOnly = true; credDelta -= 6; coachKey = `coach_r3_gridonly`;
                } else if (d.accessSplit >= 35) {
                    credDelta += 5;
                    if (coachKey === `coach_r3_glide`) coachKey = `coach_r3_leastcost`;
                }

                // Performance-based regulation improves utility solvency and collections.
                if (d.incentive === `pbr`) { subsidyDelta -= 0.4; credDelta += 6; }
                else { credDelta -= 2; }

                summaryKey = (d.tariff !== `shock` || d.lifeline === `yes`) && !ds.gridOnly && d.incentive === `pbr`
                    ? `sum_r3_good`
                    : (ds.tariffRollback ? `sum_r3_rollback`
                        : (ds.gridOnly ? `sum_r3_gridonly` : `sum_r3_weak`));
                if (d.tariff === `glide` && d.lifeline === `yes` && d.accessSplit >= 35 && d.incentive === `pbr`) {
                    coachKey = `coach_r3_strong`;
                }
            } else if (round === 4) {
                // ----- Defend the plan and manage the live shock. -----
                switch (d.shock) {
                    case `shell`:
                        // Awarding the shell fills volume on paper but never delivers power (sticky).
                        ds.shellAwarded = true; ds.shockMishandled = true;
                        ds.capacityMW = Math.round(ds.capacityMW * 0.55); // the shell's MW never arrive
                        credDelta -= 16; coachKey = `coach_r4_shell`; break;
                    case `shell_dq`:
                        // Disqualify it: take lower volume now, protect delivery and credibility.
                        credDelta += 10; coachKey = `coach_r4_shelldq`; break;
                    case `protest`:
                        // Conceding the rollback loses the revenue and the independence (sticky).
                        ds.tariffRollback = true; ds.shockMishandled = true;
                        subsidyDelta += 0.5; credDelta -= 12; coachKey = `coach_r4_protest`; break;
                    case `protest_hold`:
                        credDelta += 9; coachKey = `coach_r4_protesthold`; break;
                    case `drought`:
                        // Answering the hydro shock with emergency diesel — the trap response.
                        // Even if it squeaks under the ceiling, abandoning the reform for diesel
                        // is never the top-verdict play.
                        ds.shockMishandled = true;
                        subsidyDelta += 1.4; credDelta -= 8; coachKey = `coach_r4_drought`; break;
                    case `drought_renew`:
                        accessDelta += 0; credDelta += 7; coachKey = `coach_r4_droughtrenew`; break;
                }

                // The defence and the staked metric (decision tree #1, #6 — measuring the right thing).
                ds.framingSound = (d.defense === `integrated` && d.metric === `delivered`);
                switch (d.defense) {
                    case `integrated`: credDelta += 8; break;
                    case `capacity`:   credDelta -= 5; coachKey = (coachKey === `coach_default`) ? `coach_r4_capacityonly` : coachKey; break;
                    case `spin`:       credDelta -= 7; coachKey = (coachKey === `coach_default`) ? `coach_r4_spin` : coachKey; break;
                }
                if (d.metric === `delivered`) { credDelta += 7; }
                else if (d.metric === `lowestbid`) { credDelta -= 5; }
                else { credDelta -= 2; }

                if (d.conviction >= 60) { credDelta += 3; }
                else if (d.conviction <= 25) { credDelta -= 3; }

                summaryKey = (d.shock.indexOf(`_`) > -1 && d.defense === `integrated` && d.metric === `delivered`)
                    ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.capacityMW = Math.max(0, Math.min(this.CAP_TARGET, Math.round(ds.capacityMW)));
            ds.accessPct = Math.max(0, Math.min(100, Math.round((ds.accessPct + accessDelta) * 10) / 10));
            ds.subsidyDrawn = Math.max(0, Math.round((ds.subsidyDrawn + subsidyDelta) * 100) / 100);
            ds.credibility = Math.max(0, Math.min(100, Math.round(ds.credibility + credDelta)));

            // ---- Sticky ceiling breach: subsidy above ZMK 4.1bn fails the directive.
            // Only latched from Round 3 onward, once the tariff lever exists to fund the
            // plan — an early-round credit-enhancement outlay that the glide-path then
            // covers is not a breach. The plan is reconciled against the ceiling at review. ----
            if (round >= 3 && ds.subsidyDrawn > this.SUBSIDY_CEILING + 0.001) {
                ds.subsidyBreached = true;
            }

            // ---- A failed auction or a shell award caps delivered capacity hard. ----
            if (ds.auctionFailed) {
                ds.capacityMW = Math.min(ds.capacityMW, 120);
            }

            ds.capacityHistory.push(ds.capacityMW);
            ds.accessHistory.push(ds.accessPct);
            ds.subsidyHistory.push(ds.subsidyDrawn);
            ds.credibilityHistory.push(ds.credibility);

            // ---- Persist the composite where the gradebook / reporting layer reads it. ----
            // express_resolveDomainScore() reads domainState.performance.overallScore first,
            // then a top-level score; express_extractHistory() reads the same per period.
            // Without this the instructor Results panel shows "—", the per-period sparkline
            // is empty, and the gametype-20 (record_grade / AGS) post-back sends 0.
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                capacityMW: ds.capacityMW,
                capDelta: Math.round(capDelta),
                accessPct: ds.accessPct,
                clearingPrice: ds.clearingPrice,
                subsidyDrawn: ds.subsidyDrawn,
                subsidyBreached: ds.subsidyBreached,
                credibility: ds.credibility,
                auctionFailed: ds.auctionFailed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

        _credLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 65) return t(`cred_high`);
            if (v >= 45) return t(`cred_mid`);
            return t(`cred_low`);
        }

        _fmtPrice(v) {
            const n = Number(v);
            if (!n) return `—`;
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            let s = n.toFixed(2);
            if (lang === `es`) s = s.replace(`.`, `,`);
            return `ZMK ` + s;
        }

        _fmtSubsidy(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            let s = Number(v).toFixed(1);
            if (lang === `es`) s = s.replace(`.`, `,`);
            return `ZMK ` + s + `bn`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`capacityDisplay`, `domainState.capacityMW`, (v) => {
                const mw = Math.round(Number(v));
                const card = document.querySelector(`.powergrid-card-capacity`);
                if (card) {
                    card.classList.toggle(`powergrid-cap-good`, mw >= self.CAP_TARGET - 60);
                    card.classList.toggle(`powergrid-cap-bad`, mw > 0 && mw < 200);
                }
                return `${mw} MW`;
            });

            uiManager.bind(`accessDisplay`, `domainState.accessPct`, (v) => {
                const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
                let s = Number(v).toFixed(1);
                if (lang === `es`) s = s.replace(`.`, `,`);
                return `${s}%`;
            });

            uiManager.bind(`priceDisplay`, `domainState.clearingPrice`, (v) => self._fmtPrice(v));

            uiManager.bind(`subsidyDisplay`, `domainState.subsidyDrawn`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.powergrid-card-subsidy`);
                if (card) card.classList.toggle(`powergrid-sub-breach`, n > self.SUBSIDY_CEILING + 0.001);
                return self._fmtSubsidy(n);
            });

            uiManager.bind(`credDisplay`, `domainState.credibility`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.powergrid-cred-bar`);
                if (bar) {
                    bar.classList.toggle(`powergrid-cred-high`, n >= 65);
                    bar.classList.toggle(`powergrid-cred-mid`, n >= 45 && n < 65);
                }
                return self._credLabel(n);
            });

            // Range slider readouts.
            const wire = (inputId, readoutId) => {
                const inp = document.getElementById(inputId);
                const out = document.getElementById(readoutId);
                if (inp && out) {
                    out.textContent = inp.value;
                    inp.addEventListener(`input`, function() { out.textContent = inp.value; });
                }
            };
            wire(`rigourInput`, `rigourReadout`);
            wire(`contentInput`, `contentReadout`);
            wire(`accessSplitInput`, `accessSplitReadout`);

            // Accessibility: the visible prompts are separate data-i18n elements not
            // tied to their control (no <label for>), so a screen reader would announce
            // an unlabeled <select>. Mirror each prompt onto the control via aria-label,
            // using t() so it is correct in each language.
            const tA = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const ariaMap = {
                constraintInput: `r1_constraint_label`, riskInput: `r1_risk_label`,
                systemsInput: `r1_systems_label`, rigourInput: `r1_rigour_label`,
                volumeInput: `r2_volume_label`, reserveInput: `r2_reserve_label`,
                creditInput: `r2_credit_label`, qualInput: `r2_qual_label`,
                contentInput: `r2_content_label`, tariffInput: `r3_tariff_label`,
                lifelineInput: `r3_lifeline_label`, accessSplitInput: `r3_access_label`,
                incentiveInput: `r3_incentive_label`, shockInput: `r4_shock_label`,
                defenseInput: `r4_defense_label`, metricInput: `r4_metric_label`,
                convictionInput: `r4_conviction_label`
            };
            Object.keys(ariaMap).forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.setAttribute(`aria-label`, tA(ariaMap[id]));
            });
        }

        getChartConfig() {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            return {
                gridChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t(`chart_ds_capacity`),
                                data: [],
                                borderColor: `#1f9e76`,
                                backgroundColor: `rgba(31,158,118,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#1f9e76`,
                                yAxisID: `y`
                            },
                            {
                                label: t(`chart_ds_access`),
                                data: [],
                                borderColor: `#e08a1e`,
                                backgroundColor: `rgba(224,138,30,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#e08a1e`,
                                yAxisID: `y`
                            },
                            {
                                label: t(`chart_ds_cred`),
                                data: [],
                                borderColor: `#2563a8`,
                                backgroundColor: `rgba(37,99,168,0.08)`,
                                borderWidth: 2,
