        getChartData(state) {
            const ds = (state && state.domainState) || {};
            const _accessHistory = ds.accessHistory || [];
            const _capacityHistory = ds.capacityHistory || [];
            const _credibilityHistory = ds.credibilityHistory || [];
            const _subsidyHistory = ds.subsidyHistory || [];
            const labels = _capacityHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            const capPct = _capacityHistory.map((v) => Math.round((v / this.CAP_TARGET) * 100));
            const subsidyPct = _subsidyHistory.map((v) => Math.round((v / this.SUBSIDY_CEILING) * 100));
            return {
                gridChart: {
                    labels: labels,
                    datasets: [
                        { data: capPct },
                        { data: _accessHistory.map((v) => Math.round(v)) },
                        { data: _credibilityHistory.map((v) => Math.round(v)) },
                        { data: subsidyPct }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const capacity = Math.round(ds.capacityMW);
            const access = Math.round(ds.accessPct * 10) / 10;
            const subsidy = Math.round(ds.subsidyDrawn * 100) / 100;
            const credibility = Math.round(ds.credibility);

            // A clearing price at or below the realistic discovery ceiling is bankable
            // and disciplined; above it, ratepayers are overpaying for the same megawatts.
            const priceEfficient = ds.clearingPrice > 0 && ds.clearingPrice <= 0.86 && !ds.auctionFailed;

            // Did each Cabinet target land?
            // A credible first tranche (e.g. 400 MW clearing ~90% → ~360 MW) puts the
            // programme on track to the 600 MW 24-month target — the concept endorses
            // holding volume back for a learned second round, so a disciplined first
            // tranche counts as hitting capacity. A token 150 MW pilot (~135 MW), a
            // failed auction or an awarded shell do not.
            const hitCapacity = capacity >= 300 && !ds.auctionFailed && !ds.shellAwarded;
            const withinCeiling = !ds.subsidyBreached && subsidy <= this.SUBSIDY_CEILING + 0.001;
            const hitAccess = access >= this.ACCESS_TARGET - 1.5;
            const bankable = credibility >= 60;

            // Composite, capped by sticky failures — computed by _composite(), the
            // SAME helper persisted to domainState.performance.overallScore each period,
            // so the completion score == the last per-period score by construction.
            const composite = this._composite(ds);

            const anyHeadlineError = ds.auctionFailed || ds.riskUncovered || ds.tariffRollback || ds.gridOnly || ds.shellAwarded || ds.subsidyBreached;

            let performance = `mandatelost`;
            if (hitCapacity && withinCeiling && hitAccess && bankable && priceEfficient && ds.framingSound
                && !ds.tariffUnreformed && !ds.shockMishandled
                && !anyHeadlineError && composite >= 80) {
                performance = `powered`;
            } else if (ds.auctionFailed) {
                performance = `auctionfailed`;
            } else if (ds.shellAwarded) {
                performance = `shell`;
            } else if (ds.subsidyBreached) {
                performance = `breach`;
            } else if (ds.tariffRollback) {
                performance = `rollback`;
            } else if (composite >= 60) {
                performance = `partial`;
            }

            const insights = [];
            if (performance === `powered`) insights.push(window.mySimulation.t(`insight_powered`));
            if (ds.auctionFailed) insights.push(window.mySimulation.t(`insight_auctionfailed`));
            if (ds.riskUncovered) insights.push(window.mySimulation.t(`insight_riskuncovered`));
            if (ds.tariffRollback) insights.push(window.mySimulation.t(`insight_rollback`));
            if (ds.gridOnly) insights.push(window.mySimulation.t(`insight_gridonly`));
            if (ds.shellAwarded) insights.push(window.mySimulation.t(`insight_shell`));
            if (ds.subsidyBreached) insights.push(window.mySimulation.t(`insight_breach`));
            if (ds.silosThinking) insights.push(window.mySimulation.t(`insight_silos`));
            if (!ds.diagnosedConstraint) insights.push(window.mySimulation.t(`insight_misdiagnosed`));
            if (!insights.length) insights.push(window.mySimulation.t(`insight_partial`));

            return {
                capacity: capacity,
                access: access,
                subsidy: subsidy,
                clearingPrice: ds.clearingPrice,
                credibility: credibility,
                hitCapacity: hitCapacity,
                withinCeiling: withinCeiling,
                hitAccess: hitAccess,
                bankable: bankable,
                priceEfficient: priceEfficient,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performance: performance,
                performanceKey: `grade_` + performance,
                performanceLabel: this._gradeLabel(performance),
                insights: insights
            };
        }

        // Localized completion debrief — the base class default only prints
        // "You completed N periods", discarding the composite, tier, targets,
        // KPIs and insights this sim computes. Rendered into #usf-completion-content.
        formatCompletionMessage(summary) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = summary || {};
            const composite = Number.isFinite(s.composite) ? s.composite : (this._composite(window.mySimulation.state.domainState));
            const verdict = s.performanceLabel || this._gradeLabel(s.performance || `mandatelost`);
            const top = (s.performance === `powered`);
            const esLang = (window.mySimulation && window.mySimulation.language === `es`);
            const acc = Number(s.access) || 0;
            const accStr = (esLang ? acc.toFixed(1).replace(`.`, `,`) : acc.toFixed(1)) + `%`;

            const chip = (ok, label) =>
                `<span class="pg-cm-chip ${ok ? `pg-cm-chip-ok` : `pg-cm-chip-no`}">${ok ? `✓` : `✗`} ${label}</span>`;
            const kpi = (label, value, sub) =>
                `<div class="pg-cm-kpi"><div class="pg-cm-kpi-val">${value}</div>` +
                `<div class="pg-cm-kpi-lbl">${label}</div>` +
                (sub ? `<div class="pg-cm-kpi-sub">${sub}</div>` : ``) + `</div>`;

            const chips = [
                chip(!!s.hitCapacity,   t(`cm_t_capacity`)),
                chip(!!s.hitAccess,     t(`cm_t_access`)),
                chip(!!s.withinCeiling, t(`cm_t_fiscal`)),
                chip(!!s.priceEfficient,t(`cm_t_price`)),
                chip(!!s.bankable,      t(`cm_t_cred`))
            ].join(``);

            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightsHtml = insights.length
                ? `<div class="pg-cm-h">${t(`cm_insights_h`)}</div><ul class="pg-cm-insights">` +
                  insights.map((x) => `<li>${x}</li>`).join(``) + `</ul>`
                : ``;

            return `
                <div class="pg-cm ${top ? `pg-cm-top` : ``}">
                    <div class="pg-cm-verdict">
                        <div class="pg-cm-score"><span class="pg-cm-score-num">${composite}</span><span class="pg-cm-score-den">/100</span></div>
                        <div class="pg-cm-verdict-txt">
                            <div class="pg-cm-badge">${verdict}</div>
                            <div class="pg-cm-sub">${t(`cm_periods_pre`)} ${s.totalPeriods || 4} ${t(`cm_periods_post`)}</div>
                        </div>
                    </div>
                    <div class="pg-cm-h">${t(`cm_targets_h`)}</div>
                    <div class="pg-cm-chips">${chips}</div>
                    <div class="pg-cm-h">${t(`cm_kpis_h`)}</div>
                    <div class="pg-cm-kpis">
                        ${kpi(t(`capacity_label`), Math.round(Number(s.capacity) || 0) + ` MW`, t(`cm_of`) + ` 600 MW`)}
                        ${kpi(t(`access_label`), accStr, t(`cm_of`) + ` 60%`)}
                        ${kpi(t(`price_label`), this._fmtPrice(s.clearingPrice), `ZMK/kWh`)}
                        ${kpi(t(`subsidy_label`), this._fmtSubsidy(s.subsidy), t(`cm_ceiling`) + ` ZMK 4.1bn`)}
                        ${kpi(t(`cred_label_short`), Math.round(Number(s.credibility) || 0), `/100`)}
                    </div>
                    ${insightsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.auctionFailed) return window.mySimulation.t(`hint_auctionfailed`);
            if (ds.shellAwarded) return window.mySimulation.t(`hint_shell`);
            if (ds.subsidyBreached) return window.mySimulation.t(`hint_breach`);
            if (ds.riskUncovered && state.currentPeriod >= 2) return window.mySimulation.t(`hint_riskuncovered`);
            if (ds.tariffRollback) return window.mySimulation.t(`hint_rollback`);
            if (ds.gridOnly) return window.mySimulation.t(`hint_gridonly`);
            if (ds.credibility >= 65 && ds.capacityMW >= this.CAP_TARGET - 80) return window.mySimulation.t(`hint_strong`);
            return null;
        }

